const body = $input.first().json.body || $input.first().json;
const topic = (body.topic || '').toString().trim();
if (!topic) throw new Error('Missing required field: topic');
return [{ json: { topic } }];

const topic = $('Validate Topic').first().json.topic;
const ai = $input.first().json;
const content = ai.choices?.[0]?.message?.content || '';
let copy = { post: content, ad: content };
try { const p = JSON.parse(content); if (p.post) copy = p; } catch (e) {}
return [{ json: {
  topic,
  copy,
  status: 'draft',
  created_at: new Date().toISOString(),
  channels: ['buffer', 'brevo']
} }];
